{"action":"edit","path":"toolformer_filter.py","old_text":"","new_text":"import numpy as np

def filter_api_calls(with_result, call_only, no_call, tau_filter):
    # Validation
    if isinstance(tau_filter, bool):
        raise ValueError("tau_filter cannot be boolean")
    for arr, name in [(with_result, 'with_result'), (call_only, 'call_only'), (no_call, 'no_call')]:
        if not isinstance(arr, np.ndarray):
            raise ValueError(f"{name} must be a numpy array")
        if arr.ndim != 2:
            raise ValueError(f"{name} must be a 2D matrix")
        if arr.size == 0:
            raise ValueError(f"{name} must not be empty")
        if not np.isfinite(arr).all():
            raise ValueError(f"{name} contains non-finite values")
        if (arr > 0).any():
            raise ValueError(f"{name} contains positive values (expected nonpositive)")
    if not (with_result.shape == call_only.shape == no_call.shape):
        raise ValueError("Input matrices must have the same shape")
    if not np.isfinite(tau_filter) or tau_filter < 0:
        raise ValueError("tau_filter must be finite and nonnegative")

    n_candidates, future_horizon = with_result.shape
    t = np.arange(future_horizon)
    raw_weights = np.maximum(0, 1 - 0.2 * t)
    normalized_weights = raw_weights / raw_weights.sum()

    L_plus = -np.sum(normalized_weights * with_result, axis=1)
    L_empty = -np.sum(normalized_weights * no_call, axis=1)
    L_call_only = -np.sum(normalized_weights * call_only, axis=1)

    L_minus = np.minimum(L_empty, L_call_only)
    margin = L_minus - L_plus
    keep = margin >= tau_filter

    return keep, margin"}
